/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

/**
 * The {@code claims} parameter (task 4.8): ID token claims asked for and released by the granted
 * scopes are added; one the scopes do not cover is not; a malformed parameter or an unavailable
 * essential claim is rejected, and discovery announces the parameter.
 */
@QuarkusTest
class ClaimsParameterFlowTest extends OidcIntegrationTestBase {

  private static final String BASE = "/oauth/openid/" + OidcTestFixtures.TENANT;

  private static Map<String, String> query(String scope, String claims) {
    Map<String, String> query = new LinkedHashMap<>();
    query.put("client_id", OidcTestFixtures.CLIENT_ID);
    query.put("redirect_uri", OidcTestFixtures.REDIRECT_URI);
    query.put("response_type", "code");
    query.put("scope", scope);
    query.put("state", OidcTestFixtures.STATE);
    query.put("claims", claims);
    return query;
  }

  private Map<String, Object> idToken(String scope, String claims) {
    Response login = RestAssured.given().redirects().follow(false).contentType(ContentType.URLENC)
        .queryParams(query(scope, claims)).formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("csid", OidcTestFixtures.CSID)
        .post(BASE + "/auth");
    String code = client.extractAuthCode(login);
    Assertions.assertNotNull(code, login.getHeader("Location"));
    Response exchange = client.exchangeCode(OidcTestFixtures.TENANT, code,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.CLIENT_ID);
    Assertions.assertEquals(200, exchange.statusCode(), exchange.getBody().asString());
    return decodeToken(exchange.jsonPath().getString("id_token"));
  }

  @Test
  void requestedClaim_coveredByTheScope_isInTheIdToken() {
    Map<String, Object> claims = idToken("openid profile", "{\"id_token\":{\"name\":null}}");
    Assertions.assertNotNull(claims.get("name"));
  }

  @Test
  void voluntaryClaim_outsideTheScopes_isNotReleased() {
    Map<String, Object> claims = idToken("openid", "{\"id_token\":{\"name\":null}}");
    Assertions.assertNull(claims.get("name"));
  }

  @Test
  void essentialClaim_outsideTheScopes_isInvalidRequest() {
    Response response = RestAssured.given().redirects().follow(false)
        .queryParams(query("openid", "{\"id_token\":{\"email\":{\"essential\":true}}}"))
        .get(BASE + "/auth");
    Assertions.assertEquals(302, response.statusCode());
    Assertions.assertTrue(response.getHeader("Location").contains("error=invalid_request"));
    Assertions.assertNotNull(
        idToken("openid profile", "{\"id_token\":{\"name\":{\"essential\":true}}}").get("name"),
        "Covered by the scope and held by the user, the request goes on");
  }

  @Test
  void essentialClaim_theUserDoesNotHave_endsTheRequest() {
    // The test user has no profile: given_name is covered by the scope but not available.
    Response login = RestAssured.given().redirects().follow(false).contentType(ContentType.URLENC)
        .queryParams(
            query("openid profile", "{\"id_token\":{\"given_name\":{\"essential\":true}}}"))
        .formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("csid", OidcTestFixtures.CSID)
        .post(BASE + "/auth");
    String location = login.getHeader("Location");
    Assertions.assertTrue(location.contains("error=access_denied"), location);
    Assertions.assertNull(client.extractAuthCode(login));
  }

  @Test
  void malformedOrUnavailable_isInvalidRequest() {
    for (String claims : new String[] {"not json", "{\"access_token\":{}}",
        "{\"id_token\":{\"name\":{\"essential\":\"yes\"}}}",
        "{\"userinfo\":{\"salary\":{\"essential\":true}}}"}) {
      Response response = RestAssured.given().redirects().follow(false)
          .queryParams(query("openid", claims)).get(BASE + "/auth");
      Assertions.assertEquals(302, response.statusCode(), claims);
      Assertions.assertTrue(response.getHeader("Location").contains("error=invalid_request"),
          claims);
    }
  }

  @Test
  void voluntaryUnknownClaim_isIgnored() {
    Assertions.assertNull(idToken("openid", "{\"id_token\":{\"salary\":null}}").get("salary"));
  }

  @Test
  void discovery_announcesTheParameter() {
    Assertions.assertTrue(RestAssured.get(BASE + "/.well-known/openid-configuration").jsonPath()
        .getBoolean("claims_parameter_supported"));
  }
}
